    /// A body, its expressions in turn: one, itself; more, `(seq ...)`.
    pub fn l0_seq(mut path: Str, mut scope: Sexps, mut env: List<&'static L0Bound>, mut next: i64, mut es: Sexps, mut done: List<Str>) -> &'static L0Made {
        loop {
            if null_p(es) {
                if (not(null_p(done)) && null_p(cdr(done))) {
                    return l0_made(car(done), next);
                } else {
                    return l0_made(string_append(str_lit("(seq "), string_append(words_of(reverse(done)), str_lit(")"))), next);
                }
            } else {
                let tagcase_ = l0_of(path, scope, env, next, car(es));
                match *tagcase_ {
                    L0Made::L0Made(t, n1) => {
                        (next, es, done) = (n1, cdr(es), kayak_rt::heap_cons(t, done));
                        continue;
                    }
                }
            }
        }
    }

    // A top-level form's term made a call of a procedure of no parameters
    // (C460), so that each form's run is a call of its own from
    // `kc_entry`'s frame, as Fixpt runs each: the frames a whole continuation
    // (`cwcc`) takes end there, and one resumed returns there. Made a term
    // here, the lambda numbered `n`, after the form's binders, with no free
    // variables (a top-level form has no local), and not a form for `l0-of`,
    // which would look its head up as a global's name first.
